sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from services import battle_engine, combat_completion, rpg_engine, progression_db
import native_combat

CONTRACT = json.loads((Path(__file__).resolve().parents[2] / "docs/fixtures/combat_task_completion.json").read_text())


def assert_contract(result, name):
    expected = CONTRACT["responses"][name]
    # Task and resolution IDs are generated by each isolated workflow.
    assert {key: result[key] for key in expected if key not in ("task_id", "resolution_id")} == {
        key: value for key, value in expected.items() if key not in ("task_id", "resolution_id")}


def subprocess_call(vault, path, body):
    backend = Path(__file__).resolve().parents[1]
    result = subprocess.run([sys.executable, str(backend / "native_combat.py")],
        input=json.dumps({"path": path, "body": body}), capture_output=True, text=True,
        env={**os.environ, "NAVIS_ROOT": str(vault), "PYTHONIOENCODING": "utf-8"}, timeout=30, check=True)
    envelope = json.loads(result.stdout)
    assert envelope["status"] == 200, envelope
    return envelope["body"]


