@pytest.fixture(params=["backend", "native", "http"])
def call(request, monkeypatch):
    if request.param == "backend":
        return combat_completion.dispatch
    if request.param == "http":
        from fastapi.testclient import TestClient
        import main
        # Do not start lifespan jobs: this client only exercises the HTTP routes.
        client = TestClient(main.app)
        def http(path, body):
            response = client.post(path, json=body)
            if response.status_code != 200:
                raise ValueError(response.json()["detail"])
            return response.json()
        return http
    def native(path, body):
        output = io.StringIO()
        monkeypatch.setattr(sys, "stdin", io.StringIO(json.dumps({"path": path, "body": body})))
        monkeypatch.setattr(sys, "stdout", output)
        native_combat.main()
        envelope = json.loads(output.getvalue())
        if envelope["status"] != 200:
            raise ValueError(envelope["body"]["detail"])
        return envelope["body"]
    return native


def link(call):
    result = call("/api/battle/link", {"task_id": "task-1", "top_card_id": "a", "bottom_card_id": "b",
        "source": {"path": "Journal/2026/09/2026-09-30.md", "target_text": "Repair telescope"}})
    return {"task_id": "task-1", "resolution_id": result["resolution_id"], "source": result["source"], "is_completed": True}


def state(vault):
    return json.loads((vault / "Battle/battle_state.json").read_text(encoding="utf-8-sig"))


@pytest.mark.parametrize("bom,newline", [(True, b"\r\n"), (True, b"\n"), (False, b"\r\n"), (False, b"\n")])
def test_success_and_replay_preserve_bytes_and_xp(vault, call, bom, newline):
    journal = vault / "Journal/2026/09/2026-09-30.md"
    raw = journal.read_bytes().replace(b"\r\n", newline)
    journal.write_bytes(raw if bom else raw[3:])
    command = link(call)
    journal = vault / command["source"]["path"]
    before = journal.read_bytes()
    result = call("/api/battle/resolve", command)
    assert_contract(result, "completed")
    assert result["status"] == "completed", result.get("message")
    assert journal.read_bytes() == before.replace(b"[ ]", b"[x]", 1)
    assert list(journal.parent.glob("*.backup_combat_*"))[0].read_bytes() == before
    ledger = progression_db.get_source_states("journal_daily", "Journal/2026/09/30.md#daily-xp")
    replay = call("/api/battle/resolve", command)
    assert_contract(replay, "same_key_retry")
    assert replay["idempotent_replay"]
    assert replay["xp_sync"] == "not_repeated"
    assert progression_db.get_source_states("journal_daily", "Journal/2026/09/30.md#daily-xp") == ledger
    assert state(vault)["discard"] == ["a"]
    assert state(vault)["lost"] == ["b"]
    assert len(progression_db.get_xp_history(entity_id="keeper")) == 1
    with pytest.raises(ValueError, match="conflict"):
        call("/api/battle/resolve", {**command, "is_completed": False})


@pytest.mark.parametrize("change", ["missing", "edited", "moved", "duplicate"])
def test_invalid_sources_leave_cards_linked(vault, call, change):
    command = link(call)
    journal = vault / command["source"]["path"]
    if change == "missing":
        journal.unlink()
    elif change == "edited":
        journal.write_bytes(journal.read_bytes().replace(b"telescope", b"satellite"))
    elif change == "moved":
        journal.write_bytes(b"New line\r\n" + journal.read_bytes())
    else:
        journal.write_bytes(journal.read_bytes() + b"- [ ] Repair telescope\r\n")
    before = state(vault)
    with pytest.raises((ValueError, FileNotFoundError)):
        call("/api/battle/resolve", command)
    assert state(vault) == before


def test_already_complete_and_false_resolution(vault, call):
    command = link(call)
    journal = vault / command["source"]["path"]
    journal.write_bytes(journal.read_bytes().replace(b"[ ]", b"[x]"))
    assert call("/api/battle/resolve", command)["status"] == "already_completed"
    assert call("/api/battle/resolve", command)["idempotent_replay"]
    with pytest.raises(ValueError, match="conflict"):
        call("/api/battle/resolve", {**command, "is_completed": False})
    assert state(vault)["active_links"]
    journal.write_bytes(journal.read_bytes().replace(b"[x]", b"[ ]"))
    cancelled = call("/api/battle/resolve", {**command, "resolution_id": "cancel-fixture", "is_completed": False})
    assert_contract(cancelled, "cancelled")
    assert call("/api/battle/resolve", {**command, "resolution_id": "cancel-fixture", "is_completed": False})["idempotent_replay"]
    assert b"[ ]" in journal.read_bytes()
    assert not (vault / "Keeper/navis_progression.db").exists()


@pytest.mark.parametrize("failing_save", [2, 3, 4, 5])
def test_partial_write_recovery(vault, call, monkeypatch, failing_save):
    command = link(call)
    save = battle_engine.BattleEngine.save_state
    count = 0
    def fail_once(engine):
        nonlocal count
        count += 1
        if count == failing_save:
            raise OSError("Synthetic battle write failure")
        save(engine)
    monkeypatch.setattr(battle_engine.BattleEngine, "save_state", fail_once)
    result = call("/api/battle/resolve", command)
    assert result["status"] == "pending_recovery"
    assert b"[x]" in (vault / command["source"]["path"]).read_bytes()
    monkeypatch.setattr(battle_engine.BattleEngine, "save_state", save)
    assert call("/api/battle/resolve", command)["status"] == "completed"
    assert state(vault)["discard"] == ["a"]
    assert state(vault)["lost"] == ["b"]


def test_journal_write_failure_and_xp_retry(vault, call, monkeypatch):
    command = link(call)
    atomic = combat_completion.atomic_bytes
    def fail_journal(path, data):
        if path.suffix == ".md":
            raise OSError("Synthetic journal write failure")
        atomic(path, data)
    monkeypatch.setattr(combat_completion, "atomic_bytes", fail_journal)
    assert call("/api/battle/resolve", command)["status"] == "pending_recovery"
    assert state(vault)["active_links"]
    assert b"[ ]" in (vault / command["source"]["path"]).read_bytes()
    monkeypatch.setattr(combat_completion, "atomic_bytes", atomic)
    sync = rpg_engine.calculate_and_apply_xp
    monkeypatch.setattr(rpg_engine, "calculate_and_apply_xp", lambda **kw: (_ for _ in ()).throw(OSError("Synthetic XP failure")))
    result = call("/api/battle/resolve", command)
    assert result["cards_resolved"] and result["status"] == "pending_recovery"
    monkeypatch.setattr(rpg_engine, "calculate_and_apply_xp", sync)
    assert call("/api/battle/resolve", command)["status"] == "completed"
    assert state(vault)["discard"] == ["a"]


def test_native_real_subprocess(vault):
    backend = Path(__file__).resolve().parents[1]
    def native(path, body):
        result = subprocess.run([sys.executable, str(backend / "native_combat.py")],
            input=json.dumps({"path": path, "body": body}), capture_output=True, text=True,
            env={**os.environ, "NAVIS_ROOT": str(vault), "PYTHONIOENCODING": "utf-8"}, timeout=30, check=True)
        return json.loads(result.stdout)["body"]
    command = link(native)
    assert native("/api/battle/resolve", command)["status"] == "completed"
    assert native("/api/battle/resolve", command)["idempotent_replay"]


def test_intent_failure_prevents_task_write(vault, call, monkeypatch):
    command = link(call)
    before = state(vault)
    journal = vault / command["source"]["path"]
    raw = journal.read_bytes()
    monkeypatch.setattr(battle_engine.BattleEngine, "save_state", lambda engine: (_ for _ in ()).throw(OSError("intent unavailable")))
    with pytest.raises((OSError, ValueError)):
        call("/api/battle/resolve", command)
    assert state(vault) == before
    assert journal.read_bytes() == raw


