@pytest.mark.parametrize("path", ["../outside.md", "/absolute.md", "C:/absolute.md"])
def test_unsafe_source_paths_fail_without_consuming_cards(vault, call, path):
    before = state(vault)
    with pytest.raises(ValueError):
        call("/api/battle/link", {"task_id":"fixture", "top_card_id":"a", "bottom_card_id":"b", "source":{"path":path,"target_text":"Repair telescope"}})
    assert state(vault) == before


def test_fastapi_handlers_use_the_shared_completion_contract(vault):
    import main
    linked = asyncio.run(main.link_battle_task(main.BattleLinkRequest(
        task_id="http-fixture", top_card_id="a", bottom_card_id="b",
        source={"path":"Journal/2026/09/2026-09-30.md", "target_text":"Repair telescope"})))
    command = main.BattleResolveRequest(task_id="http-fixture", resolution_id=linked["resolution_id"], source=linked["source"])
    result = asyncio.run(main.resolve_battle_task(command))
    assert result["status"] == "completed", result.get("message")
    assert asyncio.run(main.resolve_battle_task(command))["idempotent_replay"]


@pytest.mark.parametrize("proposed", [("c", "d"), ("a", "b")])
def test_duplicate_link_preserves_all_cards_and_saved_bytes(vault, call, proposed):
    path = vault / "Battle/battle_state.json"
    initial = {"hand": ["a", "b", "c", "d"], "discard": ["e"], "lost": ["f"], "active_links": {}}
    path.write_text(json.dumps(initial))
    link(call)
    before = path.read_bytes()
    original = state(vault)
    with pytest.raises(ValueError, match="Task already linked; resolve or cancel it before relinking."):
        call("/api/battle/link", {"task_id": "task-1", "top_card_id": proposed[0],
            "bottom_card_id": proposed[1], "source": {"path": "missing.md"}})
    assert path.read_bytes() == before
    assert state(vault) == original
    saved = state(vault)
    cards = saved["hand"] + saved["discard"] + saved["lost"]
    for active in saved["active_links"].values():
        cards.extend([active["top"], active["bottom"]])
    assert sorted(cards) == list("abcdef")
